      "name": "request_approval",
      "target": "report",
      "requires_grant": true
    },
    {
      "name": "delete_draft",
      "target": "draft-1",
      "requires_grant": true
    },
    {
      "name": "transfer_ownership",
      "target": "report",
      "requires_grant": true
    }
